async function generarPassword(){try{const response=await fetch("?handler=GenerarPassword"),data=await response.json(),nuevaPasswordInput=document.getElementById("modelo-nueva-password"),confirmarPasswordInput=document.getElementById("modelo-confirmar-password");nuevaPasswordInput&&(nuevaPasswordInput.value=data.password);confirmarPasswordInput&&(confirmarPasswordInput.value=data.password)}catch(error){console.error("Error al generar contraseña:",error);alert("Error al generar la contraseña. Por favor, inténtalo manualmente.")}}function togglePasswordVisibility(button){const targetId=button.getAttribute("data-toggle-password"),passwordInput=document.getElementById(targetId),showIcon=button.querySelector(".eye-icon-show"),hideIcon=button.querySelector(".eye-icon-hide");passwordInput&&(passwordInput.type==="password"?(passwordInput.type="text",showIcon.style.display="none",hideIcon.style.display="block"):(passwordInput.type="password",showIcon.style.display="block",hideIcon.style.display="none"))}document.addEventListener("DOMContentLoaded",function(){const btnGenerarPassword=document.querySelector("[data-js-generar-password]");btnGenerarPassword&&btnGenerarPassword.addEventListener("click",generarPassword);const passwordToggles=document.querySelectorAll("[data-toggle-password]");passwordToggles.forEach(toggle=>{toggle.addEventListener("click",function(e){e.preventDefault();togglePasswordVisibility(this)})})});